class Ship:
    def __init__(self, name, fuel):
        self.name = name
        self.fuel = fuel

    def burn(self, amount):
        self.fuel = max(0, self.fuel - amount)

hero = Ship("Nova", 50)
alias = hero
alias.burn(15)
print(hero.name, hero.fuel)

